<?php use Sigesp\Core\{Auth,View}; $title='Atletas'; $q=http_build_query(array_filter(['q'=>$filters['q'],'status'=>$filters['status'],'por_pagina'=>$result['per_page']])); ?><section class="page-head"><div><p class="eyebrow">Gestão de atletas</p><h1>Atletas</h1><p><?= $result['total'] ?> registro(s) encontrado(s).</p></div><?php if(Auth::can('atletas.criar')): ?><a class="primary link-button" href="/atletas/novo">Novo atleta</a><?php endif; ?></section><form class="filters" method="get"><label>Buscar<input name="q" value="<?= View::e($filters['q']) ?>" placeholder="Nome, CPF ou código"></label><label>Situação<select name="status"><option value="">Todas</option><?php foreach(['ativo'=>'Ativo','inativo'=>'Inativo','rascunho'=>'Rascunho'] as $v=>$l): ?><option value="<?= $v ?>" <?= $filters['status']===$v?'selected':'' ?>><?= $l ?></option><?php endforeach ?></select></label><label>Por página<select name="por_pagina"><?php foreach([15,30,50] as $n): ?><option <?= $result['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach ?></select></label><button class="secondary">Aplicar</button><a href="/atletas">Limpar</a></form><?php if(!$result['items']): ?><section class="empty"><h2>Nenhum atleta encontrado</h2><p><?= $filters['q']||$filters['status']?'Ajuste ou limpe os filtros para tentar novamente.':'Comece cadastrando o primeiro atleta.' ?></p></section><?php else: ?><section class="table-wrap"><table><thead><tr><th>Código</th><th>Nome</th><th>CPF</th><th>Idade</th><th>Modalidade</th><th>Situação</th><th></th></tr></thead><tbody><?php foreach($result['items'] as $item): ?><tr><td><?= View::e($item['codigo']) ?></td><td><strong><?= View::e($item['nome']) ?></strong></td><td><?= View::e($item['cpf']) ?></td><td><?= (new DateTimeImmutable($item['nascimento']))->diff(new DateTimeImmutable('today'))->y ?></td><td><?= View::e($item['modalidade'] ?? '—') ?></td><td><span class="badge <?= View::e($item['status']) ?>"><?= View::e($item['status']) ?></span></td><td><a href="/atletas/<?= $item['id'] ?>">Ver perfil</a></td></tr><?php endforeach ?></tbody></table></section><nav class="pagination" aria-label="Paginação"><?php for($p=max(1,$result['page']-2);$p<=min((int)ceil($result['total']/$result['per_page']),$result['page']+2);$p++): ?><a class="<?= $p===$result['page']?'current':'' ?>" href="/atletas?<?= $q ?>&page=<?= $p ?>"><?= $p ?></a><?php endfor ?></nav><?php endif; ?>
